CREATE TABLE IF NOT EXISTS departments(department_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,department_name VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(500));
CREATE TABLE IF NOT EXISTS positions(position_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,position_name VARCHAR(100) NOT NULL UNIQUE,salary_rate NUMERIC(10,2) NOT NULL,department_id INTEGER REFERENCES departments(department_id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS accounts(account_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN('admin','hr','manager','employee')),status VARCHAR(10) DEFAULT 'active' NOT NULL CHECK(status IN('active','inactive','locked')));
CREATE TABLE IF NOT EXISTS employees(employee_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,account_id INTEGER UNIQUE REFERENCES accounts,department_id INTEGER NOT NULL REFERENCES departments,position_id INTEGER NOT NULL REFERENCES positions,manager_id INTEGER REFERENCES employees,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,phone VARCHAR(20),address VARCHAR(500),hire_date DATE NOT NULL,day_off INTEGER DEFAULT 10 NOT NULL,employment_status VARCHAR(10) DEFAULT 'active' NOT NULL CHECK(employment_status IN('active','on_leave','resigned')));
CREATE TABLE IF NOT EXISTS reports(report_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees,report_type VARCHAR(50) NOT NULL,created_date TIMESTAMP DEFAULT now(),data TEXT);
CREATE TABLE IF NOT EXISTS resignations(resignation_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees,request_date DATE DEFAULT CURRENT_DATE NOT NULL,effective_date DATE NOT NULL,reason VARCHAR(1000),status VARCHAR(10) DEFAULT 'approved' NOT NULL CHECK(status IN('pending','approved','rejected','cancelled')));
